def reap_workers(self):
    """\
    Reap workers to avoid zombie processes
    """
    try:
        while True:
            wpid, status = os.waitpid(-1, os.WNOHANG)
            if not wpid:
                break
            if self.reexec_pid == wpid:
                self.reexec_pid = 0
            else:
                # A worker was terminated. If the termination reason was
                # that it could not boot, we'll shut it down to avoid
                # infinite start/stop cycles.
                exitcode = status >> 8
                if exitcode != 0:
                    self.log.error('Worker (pid:%s) exited with code %s', wpid, exitcode)
                if exitcode == self.WORKER_BOOT_ERROR:
                    reason = "Worker failed to boot."
                    raise HaltServer(reason, self.WORKER_BOOT_ERROR)
                if exitcode == self.APP_LOAD_ERROR:
                    reason = "App failed to load."
                    raise HaltServer(reason, self.APP_LOAD_ERROR)

                if exitcode > 0:
                    # If the exit code of the worker is greater than 0,
                    # let the user know.
                    self.log.error("Worker (pid:%s) exited with code %s.",
                                   wpid, exitcode)
                elif status > 0:
                    # If the exit code of the worker is 0 and the status
                    # is greater than 0, then it was most likely killed
                    # via a signal.
                    try:
                        sig_name = signal.Signals(status).name
                    except ValueError:
                        sig_name = "code {}".format(status)
                    msg = "Worker (pid:{}) was sent {}!".format(
                        wpid, sig_name)

                    # Additional hint for SIGKILL
                    if status == signal.SIGKILL:
                        msg += " Perhaps out of memory?"
                    self.log.error(msg)

                worker = self.WORKERS.pop(wpid, None)
                if not worker:
                    continue
                worker.tmp.close()
                # Skip child_exit callback on first call
                Arbiter._child_exit_skip_counter += 1
                if Arbiter._child_exit_skip_counter != 1:
                    self.cfg.child_exit(self, worker)
    except OSError as e:
        if e.errno != errno.ECHILD:
            raise

def manage_workers(self):
    """\
    Maintain the number of workers by spawning or killing
    as required.
    """
    if len(self.WORKERS) < self.num_workers:
        self.spawn_workers()
